from fastapi import FastAPI, APIRouter
import pytest
from fastapi.testclient import TestClient
import os
import shutil

def test_frontend_not_implemented():
    app = FastAPI()
    try:
        app.frontend("/", directory="dist")
    except AttributeError:
        print("FastAPI.frontend not implemented")
        raise

    router = APIRouter()
    try:
        router.frontend("/", directory="dist")
    except AttributeError:
        print("APIRouter.frontend not implemented")
        raise

if __name__ == "__main__":
    try:
        test_frontend_not_implemented()
    except AttributeError:
        print("Caught expected AttributeError")
    except Exception as e:
        print(f"Caught unexpected exception: {e}")

